mapper.select:
SELECT
  REQUEST_IDX, MANAGE_CODE, USER_KEY, MEMBER_ID, MEMBER_NAME,
  REG_NO, BOOK_NAME, AUTHOR, REQUEST_STATUS, GETCODEIDTOCODENAME('CMS', 'DR000',REQUEST_STATUS) AS REQUEST_STATUS_NAME,
  DELETE_YN, DEVICE_CODE, (SELECT PICKUP_PLACE FROM DRONE_LOAN_DEVICE_SETTING WHERE MANAGE_CODE = DLR.MANAGE_CODE AND DEVICE_CODE = DLR.DEVICE_CODE AND USE_YN = 'Y') AS PICKUP_PLACE,
  ADD_DATE, ADD_ID, ADD_IP, MODIFY_DATE, MODIFY_ID, MODIFY_IP
FROM
    DRONE_LOAN_REQUEST DLR
WHERE  REQUEST_IDX = #{request_idx}
AND MANAGE_CODE = #{manage_code}
AND USER_KEY = #{user_key}

SELECT
  REQUEST_STATUS, GETCODEIDTOCODENAME('CMS', 'DR000',REQUEST_STATUS) AS REQUEST_STATUS_NAME,
  PREV_REQUEST_STATUS, GETCODEIDTOCODENAME('CMS', 'DR000',PREV_REQUEST_STATUS) AS PREV_REQUEST_STATUS_NAME,
  WORK_DATE, WORK_ID, WORK_IP
FROM
  DRONE_LOAN_REQUEST_LOG
WHERE REQUEST_IDX = #{request_idx}
  AND MANAGE_CODE = #{manage_code}
  AND USER_KEY = #{user_key}
ORDER BY WORK_DATE DESC

SELECT
  DECODE(COUNT(*), 0, 'N' , 'Y')
FROM
    DRONE_LOAN_REQUEST
WHERE MANAGE_CODE = #{manage_code}
AND MEMBER_ID = #{member_id}
AND TRUNC(ADD_DATE) = TRUNC(SYSDATE)
AND REG_NO = #{reg_no}
AND REQUEST_STATUS != '0000'

mapper.update:
UPDATE
  DRONE_LOAN_REQUEST
SET
  REQUEST_STATUS = #{request_status},
  MODIFY_DATE = SYSDATE,
  MODIFY_ID = #{modify_id},
  MODIFY_IP = #{modify_ip}
WHERE REQUEST_IDX = #{request_idx}
  AND MANAGE_CODE = #{manage_code}
  AND USER_KEY = #{user_key}
